import{_ as a,o as t,c as n,a1 as s}from"./chunks/framework.Ccs17H5l.js";const m=JSON.parse('{"title":"Redimensionner une image","description":"","frontmatter":{},"headers":[],"relativePath":"tool/image-resizing.md","filePath":"tool/image-resizing.md"}'),i={name:"tool/image-resizing.md"};function r(o,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="redimensionner-une-image" tabindex="-1">Redimensionner une image <a class="header-anchor" href="#redimensionner-une-image" aria-label="Permalink to &quot;Redimensionner une image&quot;">​</a></h1><p>L&#39;écran de la NumWorks fait 320 × 240 pixels, et une image prend 2 octets par pixel une fois convertie en <a href="./../reference/formats/eif.html">EIF</a>. Mieux vaut donc redimensionner les images avant de les mettre dans <code>assets/</code>, plutôt que de laisser un grand fichier occuper de la place pour rien.</p><p><a href="https://imagemagick.org" target="_blank" rel="noreferrer">ImageMagick</a> le fait en une ligne de commande.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">sudo</span><span style="color:#CE9178;"> apt</span><span style="color:#CE9178;"> install</span><span style="color:#CE9178;"> imagemagick</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Selon la version installée, la commande s&#39;appelle <code>convert</code> (version 6, celle de la plupart des distributions) ou <code>magick</code> (version 7). Les exemples ci-dessous utilisent <code>convert</code> ; remplace-la par <code>magick</code> si besoin.</p><h2 id="choisir-la-taille" tabindex="-1">Choisir la taille <a class="header-anchor" href="#choisir-la-taille" aria-label="Permalink to &quot;Choisir la taille&quot;">​</a></h2><p><code>-resize 64x64</code> fait tenir l&#39;image dans un carré de 64 × 64 en gardant ses proportions : une image 200 × 100 devient 64 × 32. Pour obtenir exactement 64 × 64 quitte à la déformer, ajoute <code>!</code> : <code>-resize &#39;64x64!&#39;</code>.</p><p>Pour l&#39;icône de l&#39;application (<code>assets/icon.png</code>), la taille doit être exactement 55 × 56 :</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">convert</span><span style="color:#CE9178;"> icone.png</span><span style="color:#569CD6;"> -resize</span><span style="color:#CE9178;"> &#39;55x56!&#39;</span><span style="color:#CE9178;"> assets/icon.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="choisir-le-filtre" tabindex="-1">Choisir le filtre <a class="header-anchor" href="#choisir-le-filtre" aria-label="Permalink to &quot;Choisir le filtre&quot;">​</a></h2><p>Le filtre est la méthode de calcul des nouveaux pixels. Selon le type d&#39;image, le résultat n&#39;est pas le même.</p><table tabindex="0"><thead><tr><th>Image</th><th>Commande</th><th>Effet</th></tr></thead><tbody><tr><td>Cas général (recommandé)</td><td><code>convert in.png -resize 64x64 -filter Lanczos -define filter:blur=0.9 out.png</code></td><td>net, peu de défauts, bon contraste</td></tr><tr><td>Rendu plus doux</td><td><code>convert in.png -resize 64x64 -filter Mitchell out.png</code></td><td>moins net</td></tr><tr><td>Photo</td><td><code>convert in.png -resize 64x64 -filter Cubic out.png</code></td><td>garde les détails sans les accentuer</td></tr><tr><td>Pixel art, icônes nettes</td><td><code>convert in.png -resize 64x64 -filter Point out.png</code></td><td>aucun lissage, les pixels restent carrés</td></tr><tr><td>Très net</td><td><code>convert in.png -resize 64x64 -filter LanczosSharp out.png</code></td><td>peut créer des halos autour des contours</td></tr><tr><td>Réduction d&#39;un facteur entier</td><td><code>convert in.png -sample 64x64 out.png</code></td><td>garde un pixel sur deux (si l&#39;image fait 128 × 128), sans aucun calcul</td></tr></tbody></table><p>Pour du pixel art, utilise <code>Point</code> ou <code>-sample</code>, sinon les bords nets deviennent flous.</p><h2 id="verifier-le-resultat" tabindex="-1">Vérifier le résultat <a class="header-anchor" href="#verifier-le-resultat" aria-label="Permalink to &quot;Vérifier le résultat&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">identify</span><span style="color:#CE9178;"> assets/pain.png</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>La commande affiche la taille de l&#39;image en pixels, par exemple <code>64x64</code>.</p>',17)])])}const h=a(i,[["render",r]]);export{m as __pageData,h as default};
